    [string]$RoutingTable   = "routing-table",
    [string]$DdbRegion      = "ap-south-2",
    [string]$RedisContainer = "redis",
    [int]$RlWindow  = 65,
    [int]$ResetSecs = 32,
    [string]$ReportPath
)

$ErrorActionPreference = "Continue"
$BaseUrl = $BaseUrl.TrimEnd("/")
$script:Pass = 0
$script:Fail = 0
$script:Case = ""
$script:Results = [System.Collections.Generic.List[object]]::new()
$RUN_ID = Get-Date -Format "yyyyMMddHHmmss"

if (-not $ApiKey) {
    Write-Host "Set IBTS_API_KEY or pass -ApiKey." -ForegroundColor Red
