}

# ---------------- output helpers ----------------
function Write-Section([string]$t) { Write-Host "`n---- $t ----" -ForegroundColor Cyan }
function Start-Case([string]$id, [string]$d) {
    $script:Case = $id
    Write-Host "`n  [$id] $d" -ForegroundColor White
}
function Write-Dbg([string]$m) { Write-Host "    [DBG] $m" -ForegroundColor DarkGray }
function Assert-That([bool]$Ok, [string]$Msg) {
    if ($Ok) { Write-Host "  [PASS] $Msg" -ForegroundColor Green; $script:Pass++ }
    else     { Write-Host "  [FAIL] $Msg" -ForegroundColor Red;   $script:Fail++ }
    $script:Results.Add([pscustomobject]@{ case = $script:Case; ok = $Ok; message = $Msg })
}
function New-IdemKey { "ibts-$RUN_ID-$(New-Guid)" }
function Wait-RateLimit([string]$why) {
    if ($RlWindow -le 0) { return }
    Write-Host "  [WAIT] $RlWindow s -- $why" -ForegroundColor DarkYellow
    Start-Sleep -Seconds $RlWindow
}

# ---------------- HTTP helper (curl.exe keeps raw headers) ----------------
function Invoke-GW {
    param(
        [string]$Path,
        [string]$Method = "GET",
        $Body = $null,
        [string]$IdemKey,
        [string]$Key = $ApiKey,
        [switch]$SkipApiKey
    )
    $hdrFile = [IO.Path]::GetTempFileName()
    $outFile = [IO.Path]::GetTempFileName()
    $inFile  = $null
    $a = @("-sS", "--connect-timeout", "10", "--max-time", "30", "-X", $Method, "$BaseUrl$Path",
           "-H", "Content-Type: application/json", "-H", "User-Agent: ibts-smoke/$RUN_ID",
           "-D", $hdrFile, "-o", $outFile, "-w", "%{http_code}")
    if (-not $SkipApiKey) { $a += @("-H", "x-api-key: $Key") }
    if ($IdemKey)         { $a += @("-H", "x-idempotency-key: $IdemKey") }
    if ($null -ne $Body) {
        $inFile = [IO.Path]::GetTempFileName()
        [IO.File]::WriteAllText($inFile, ($Body | ConvertTo-Json -Depth 5), [Text.UTF8Encoding]::new($false))
        $a += @("-d", "@$inFile")
    }
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $code = & curl.exe @a
    $curlOk = ($LASTEXITCODE -eq 0)
    $sw.Stop()

    $hdrs = @{}
    foreach ($l in (Get-Content $hdrFile -ErrorAction SilentlyContinue)) {
        if ($l -match "^([A-Za-z0-9\-]+):\s*(.+)$") { $hdrs[$Matches[1].ToLower()] = $Matches[2].Trim() }
    }
    $text = Get-Content $outFile -Raw -ErrorAction SilentlyContinue
    Remove-Item $hdrFile, $outFile -Force -ErrorAction SilentlyContinue
    if ($inFile) { Remove-Item $inFile -Force -ErrorAction SilentlyContinue }
    $obj = if ($text) { $text | ConvertFrom-Json -ErrorAction SilentlyContinue } else { $null }
    $pick = { param($n) if ($obj -and $obj.$n) { "$($obj.$n)" } else { "" } }

    [ordered]@{
        httpCode = if ($curlOk) { [int]$code } else { 0 }   # 0 = network/timeout failure
        ms       = $sw.ElapsedMilliseconds
        body     = $text
        obj      = $obj
        headers  = $hdrs
        detail   = & $pick "detail"
        status   = & $pick "status"
        txn_id   = & $pick "txn_id"
        bank_rrn = & $pick "bank_rrn"
        source   = & $pick "source"
    }
}

# Sends a payment. On HTTP 429 it waits for Retry-After and retries once,
# unless -NoRetry is set (used by the rate-limit phase, where 429 is the point).
function Send-Payment {
    param(
        [string]$Payer,
        [string]$Payee,
        [int]$Paise,
        [string]$Label,
        [string]$IdemKey,
        [switch]$NoRetry
    )
    if (-not $IdemKey) { $IdemKey = New-IdemKey }
    $send = {
        Invoke-GW -Path "/api/v1/payments" -Method POST -IdemKey $IdemKey -Body @{
            payer_vpa = $Payer; payee_vpa = $Payee; amount_paise = $Paise
            idempotency_key = $IdemKey; remarks = "smoke-$RUN_ID-$Label"
        }
    }
    $r = & $send
    if ($r.httpCode -eq 429 -and -not $NoRetry) {
        $wait = $RlWindow
        $ra = 0
        if ($r.headers["retry-after"] -and [int]::TryParse($r.headers["retry-after"], [ref]$ra)) { $wait = [Math]::Min($ra + 5, 90) }
        Write-Host "    [429] rate limited -- waiting $wait s, then retrying once" -ForegroundColor DarkYellow
        Start-Sleep -Seconds $wait
        $r = & $send
    }
    return $r
}

# ---------------- cluster helpers (only used by the breaker phase) ----------------
function Set-SBIRoute([string]$Primary, [string]$Fallback) {
    Write-Dbg "SBI primary=$Primary"
    $item = @{
        bankCode         = @{ S = "SBI" }
        bankName         = @{ S = "State Bank of India" }
        primaryEndpoint  = @{ S = $Primary }
        fallbackEndpoint = @{ S = $Fallback }
        active           = @{ BOOL = $true }
        updatedAt        = @{ N = "$([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds())" }
    } | ConvertTo-Json -Depth 5
    $tmp = [IO.Path]::GetTempFileName()
    [IO.File]::WriteAllText($tmp, $item, [Text.UTF8Encoding]::new($false))
    $out = aws dynamodb put-item --region $DdbRegion --table-name $RoutingTable --item "file://$tmp" 2>&1
    $ok = ($LASTEXITCODE -eq 0)
    Remove-Item $tmp -Force
    if (-not $ok) {
        Write-Host "    [ERR] DynamoDB: $out" -ForegroundColor DarkRed
        return $false
    }
    kubectl -n $Namespace exec deploy/ibts-redis -c $RedisContainer -- redis-cli DEL "route:SBI" | Out-Null
    Start-Sleep -Milliseconds 400
    return $true
}
function Invoke-Adapter([string]$PyCode) {
    kubectl -n $Namespace exec deploy/bank-adapter -- python3 -c $PyCode 2>$null
}
function Get-BreakerState([string]$Bank) {
    $json = Invoke-Adapter "import urllib.request; print(urllib.request.urlopen('http://localhost:8082/api/v1/adapter/debug/breakers').read().decode())"
    if ([string]::IsNullOrWhiteSpace($json)) { return @{ state = "unknown"; fail_count = -1 } }
    $e = ($json | ConvertFrom-Json -ErrorAction SilentlyContinue).PSObject.Properties[$Bank.ToUpper()]
    if ($null -eq $e) { return @{ state = "closed"; fail_count = 0 } }
    return @{ state = "$($e.Value.state)"; fail_count = [int]"$($e.Value.fail_count)" }
}
function Reset-Breaker([string]$Bank) {
    Invoke-Adapter "import urllib.request; urllib.request.urlopen(urllib.request.Request('http://localhost:8082/api/v1/adapter/debug/breakers/$Bank/reset',data=b'',method='POST'))" | Out-Null
}
$GOOD = @("http://mock-bank-server:8080/mock/sbi/txn", "http://mock-bank-server:8080/mock/sbi/txn/fallback")
$BAD  = @("http://mock-bank-server:8080/mock/sbi/txn/fail", "http://mock-bank-server:8080/mock/sbi/txn/fail/fallback")

# ======================= PHASE 0 -- Pre-flight =======================
Write-Section "PHASE 0 | Pre-flight  ($BaseUrl)"
if ($BaseUrl -like "http://*") {
    Write-Host "  [WARN] Plain HTTP: the API key travels unencrypted. Put HTTPS on the ALB." -ForegroundColor Yellow
}

Start-Case "P0-01" "Gateway health through the ALB (up to 3 tries)"
for ($i = 1; $i -le 3; $i++) {
    $h = Invoke-GW -Path "/actuator/health"
    Write-Dbg "try $i http=$($h.httpCode) status=$($h.status) $($h.ms) ms"
    if ($h.httpCode -eq 200 -and $h.status -eq "UP") { break }
    Start-Sleep -Seconds 5
}
Assert-That ($h.httpCode -eq 200 -and $h.status -eq "UP") "Gateway UP  http=$($h.httpCode) ($($h.ms) ms)"
if ($h.httpCode -eq 0) {
    Write-Host "  Cannot reach the ALB (DNS, security group or timeout). Stopping." -ForegroundColor Red
    exit 2
}

Start-Case "P0-02" "Missing x-api-key -> 401/403"
$r = Invoke-GW -Path "/api/v1/payments" -Method POST -SkipApiKey -Body @{
    payer_vpa = "a@sbi"; payee_vpa = "b@sbi"; amount_paise = 100; idempotency_key = "nokey-$RUN_ID"
}
Assert-That ($r.httpCode -in 401, 403) "Rejected without key  http=$($r.httpCode)"

Start-Case "P0-03" "Wrong x-api-key -> 401/403"
$r = Invoke-GW -Path "/api/v1/payments" -Method POST -Key "wrong-$RUN_ID" -Body @{
    payer_vpa = "a@sbi"; payee_vpa = "b@sbi"; amount_paise = 100; idempotency_key = "badkey-$RUN_ID"
}
Assert-That ($r.httpCode -in 401, 403) "Rejected with bad key  http=$($r.httpCode)"

# ======================= PHASE 1 -- Idempotency =======================
Write-Section "PHASE 1 | Idempotency"
$k1 = New-IdemKey
$k2 = New-IdemKey

Start-Case "P1-01" "New key -> 200 SUCCESS source=NEW"
$r = Send-Payment "alice@sbi" "bob@sbi" 10000 "idem-first" $k1
$txn = $r.txn_id
Assert-That ($r.httpCode -eq 200 -and $r.status -eq "SUCCESS" -and $r.source -eq "NEW") "http=$($r.httpCode) status=$($r.status) source=$($r.source) txn=$txn"

Start-Case "P1-02" "Replay same key -> CACHED, same txn_id"
$r = Send-Payment "alice@sbi" "bob@sbi" 10000 "idem-replay" $k1
Assert-That ($r.httpCode -eq 200 -and $r.source -eq "CACHED" -and $r.txn_id -eq $txn) "http=$($r.httpCode) source=$($r.source) txn=$($r.txn_id)"

Start-Case "P1-03" "Third replay -> still CACHED"
$r = Send-Payment "alice@sbi" "bob@sbi" 10000 "idem-replay2" $k1
Assert-That ($r.httpCode -eq 200 -and $r.source -eq "CACHED") "http=$($r.httpCode) source=$($r.source)"

Start-Case "P1-04" "Different key -> independent NEW transaction"
$r = Send-Payment "alice@sbi" "bob@sbi" 10000 "idem-different" $k2
Assert-That ($r.httpCode -eq 200 -and $r.source -eq "NEW" -and $r.txn_id -ne $txn) "http=$($r.httpCode) source=$($r.source) txn=$($r.txn_id)"

Start-Case "P1-05" "Amount mismatch on existing key -> 422 or CACHED (no new txn)"
$r = Send-Payment "alice@sbi" "bob@sbi" 99999 "amount-mismatch" $k1
Assert-That ($r.httpCode -eq 422 -or ($r.source -eq "CACHED" -and $r.txn_id -eq $txn)) "http=$($r.httpCode) source=$($r.source)"

# ======================= PHASE 2 -- Routing =======================
Write-Section "PHASE 2 | Routing"
$routes = @(
    @("P2-01", "SBI",     "bob@sbi",        50000),
    @("P2-02", "ICICI",   "bob@okicici",    25000),
    @("P2-03", "HDFC",    "bob@okhdfcbank", 100000),
    @("P2-04", "YesBank", "bob@ybl",        15000)
)
foreach ($t in $routes) {
    Start-Case $t[0] "$($t[1]) VPA -> 200 SUCCESS"
    $r = Send-Payment "carol@sbi" $t[2] $t[3] "route-$($t[1])"
    Assert-That ($r.httpCode -eq 200 -and $r.status -eq "SUCCESS") "$($t[1]) http=$($r.httpCode) rrn=$($r.bank_rrn) detail=$($r.detail)"
}
Start-Case "P2-05" "Unknown VPA handle -> 404"
$r = Send-Payment "carol@sbi" "bob@unknownxyz" 10000 "route-unknown"
Assert-That ($r.httpCode -eq 404) "http=$($r.httpCode) detail=$($r.detail)"

Wait-RateLimit "clear the per-IP window before validation tests"

# ======================= PHASE 3 -- Input validation =======================
Write-Section "PHASE 3 | Input validation"

Start-Case "P3-01" "Missing idempotency_key -> 422"
$r = Invoke-GW -Path "/api/v1/payments" -Method POST -Body @{
    payer_vpa = "alice@sbi"; payee_vpa = "bob@sbi"; amount_paise = 10000
}
Assert-That ($r.httpCode -eq 422) "http=$($r.httpCode) detail=$($r.detail)"

$cases = @(
    @("P3-02", "Zero amount",         @{ payer_vpa = "alice@sbi"; payee_vpa = "bob@sbi"; amount_paise = 0 }),
    @("P3-03", "Negative amount",     @{ payer_vpa = "alice@sbi"; payee_vpa = "bob@sbi"; amount_paise = -500 }),
    @("P3-04", "Payer VPA without @", @{ payer_vpa = "notavpa";   payee_vpa = "bob@sbi"; amount_paise = 10000 }),
    @("P3-05", "Missing payer_vpa",   @{ payee_vpa = "bob@sbi"; amount_paise = 10000 })
)
foreach ($c in $cases) {
    Start-Case $c[0] "$($c[1]) -> 422"
    $body = $c[2]
    $body.idempotency_key = New-IdemKey
    $r = Invoke-GW -Path "/api/v1/payments" -Method POST -IdemKey $body.idempotency_key -Body $body
    Assert-That ($r.httpCode -eq 422) "http=$($r.httpCode) detail=$($r.detail)"
}

Start-Case "P3-06" "Empty body -> 422"
$r = Invoke-GW -Path "/api/v1/payments" -Method POST -IdemKey (New-IdemKey) -Body @{}
Assert-That ($r.httpCode -eq 422) "http=$($r.httpCode)"

Start-Case "P3-07" "GET unknown txn_id -> 404"
$r = Invoke-GW -Path "/api/v1/payments/nonexistent-$RUN_ID"
Assert-That ($r.httpCode -eq 404) "http=$($r.httpCode)"

Start-Case "P3-08" "GET txn_id from Phase 1 -> 200 SUCCESS"
if ($txn) {
    $r = Invoke-GW -Path "/api/v1/payments/$txn"
    Assert-That ($r.httpCode -eq 200 -and $r.status -eq "SUCCESS") "http=$($r.httpCode) status=$($r.status)"
} else {
    Write-Host "    [SKIP] no txn_id captured in Phase 1" -ForegroundColor DarkYellow
}

# ======================= PHASE 4 -- Circuit breaker (opt-in) =======================
Write-Section "PHASE 4 | Circuit breaker"
if (-not $IncludeBreaker) {
    Write-Host "  [SKIP] pass -IncludeBreaker to run (edits the SBI routing row in DynamoDB '$RoutingTable')" -ForegroundColor DarkYellow
}
elseif (-not ((Get-Command aws -ErrorAction SilentlyContinue) -and (Get-Command kubectl -ErrorAction SilentlyContinue))) {
    Write-Host "  [SKIP] aws and kubectl must be installed and logged in" -ForegroundColor DarkYellow
}
else {
    Wait-RateLimit "clear the per-IP window before the breaker tests"
    try {
        Start-Case "P4-01" "Good route -> 200, breaker healthy"
        if (-not (Set-SBIRoute $GOOD[0] $GOOD[1])) { throw "could not write the routing table" }
        $r = Send-Payment "alice@sbi" "bob@sbi" 10000 "cb-happy"
        $b = Get-BreakerState "SBI"
        Assert-That ($r.httpCode -eq 200 -and $b.fail_count -le 0) "http=$($r.httpCode) breaker=$($b.state) fail_count=$($b.fail_count)"

        Start-Case "P4-02" "Both endpoints fail -> 502 'Both primary and fallback failed'"
        [void](Set-SBIRoute $BAD[0] $BAD[1])
        $r = Send-Payment "alice@sbi" "bob@sbi" 10000 "cb-trip-A"
        $b = Get-BreakerState "SBI"
        Assert-That ($r.httpCode -eq 502 -and $r.detail -like "*Both primary and fallback failed*") "http=$($r.httpCode) detail=$($r.detail)"
        Assert-That ($b.fail_count -eq 2) "fail_count=$($b.fail_count) (expected 2; breaker state is per pod if bank-adapter has more than 1 replica)"

        Start-Case "P4-03" "Next failure trips the breaker"
        $r = Send-Payment "alice@sbi" "bob@sbi" 10000 "cb-trip-B"
        $b = Get-BreakerState "SBI"
        Assert-That ($r.httpCode -eq 502 -and $r.detail -like "*Circuit breaker open*") "http=$($r.httpCode) detail=$($r.detail)"
        Assert-That ($b.state -eq "open") "breaker state=$($b.state)"

        Start-Case "P4-04" "Open breaker short-circuits (each under 1500 ms over the ALB)"
        for ($i = 1; $i -le 3; $i++) {
            $r = Send-Payment "alice@sbi" "bob@sbi" 10000 "cb-open-$i"
            Assert-That ($r.httpCode -eq 502 -and $r.detail -like "*Circuit breaker open*" -and $r.ms -lt 1500) "req-$i http=$($r.httpCode) $($r.ms) ms"
        }

        Start-Case "P4-05" "Restore route, wait ${ResetSecs}s, half-open probe closes the breaker"
        [void](Set-SBIRoute $GOOD[0] $GOOD[1])
        Start-Sleep -Seconds $ResetSecs
        $r = Send-Payment "alice@sbi" "bob@sbi" 10000 "cb-probe"
        $b = Get-BreakerState "SBI"
        Assert-That ($r.httpCode -eq 200 -and $r.status -eq "SUCCESS") "probe http=$($r.httpCode) detail=$($r.detail)"
        Assert-That ($b.state -eq "closed") "breaker state=$($b.state)"
    }
    catch {
        Assert-That $false "Phase 4 aborted: $($_.Exception.Message)"
    }
    finally {
        # Always leave the routing row and breaker healthy, even on Ctrl+C
        Write-Host "  [TEARDOWN] restoring good SBI route and closing breaker" -ForegroundColor DarkYellow
        [void](Set-SBIRoute $GOOD[0] $GOOD[1])
        Reset-Breaker "SBI"
        $b = Get-BreakerState "SBI"
        Assert-That ($b.state -eq "closed") "teardown: breaker state=$($b.state)"
    }
}

# ======================= PHASE 5 -- Rate limiting (opt-in) =======================
Write-Section "PHASE 5 | Rate limiting"
if (-not $IncludeRateLimit) {
    Write-Host "  [SKIP] pass -IncludeRateLimit to run (blocks your public IP for ~60 s)" -ForegroundColor DarkYellow
}
else {
    Wait-RateLimit "start from a clean window"

    Start-Case "P5-01" "Burst of 30 -> some 200 then 429"
    $codes = @()
    $first429 = $null
    for ($i = 1; $i -le 30; $i++) {
        $r = Send-Payment "alice@sbi" "bob@sbi" 100 "rl-burst-$i" -NoRetry
        $codes += $r.httpCode
        if ($r.httpCode -eq 429 -and $null -eq $first429) { $first429 = $i }
        Write-Host ("    [{0,2}] HTTP={1}  {2} ms  {3}" -f $i, $r.httpCode, $r.ms, $r.detail) -ForegroundColor DarkGray
    }
    $c200 = @($codes | Where-Object { $_ -eq 200 }).Count
    $c429 = @($codes | Where-Object { $_ -eq 429 }).Count
    Write-Dbg "summary: 200=$c200  429=$c429  first-429=req#$first429"
    Assert-That ($c200 -gt 0) "at least one request succeeded before the limit (count=$c200)"
    Assert-That ($c429 -gt 0) "429 returned under burst (count=$c429 of 30, first at req#$first429)"

    Start-Case "P5-02" "429 response carries a Retry-After header"
    $checked = $false
    for ($i = 1; $i -le 5; $i++) {
        $r = Send-Payment "alice@sbi" "bob@sbi" 100 "rl-hdr-$i" -NoRetry
        if ($r.httpCode -eq 429) {
            $ra = $r.headers["retry-after"]
            Assert-That ([bool]$ra) "Retry-After present, value=$ra"
            $checked = $true
            break
        }
    }
    if (-not $checked) { Write-Host "    [SKIP] no 429 returned, nothing to check" -ForegroundColor DarkYellow }

    Start-Case "P5-03" "Window resets -> request succeeds after ${RlWindow}s"
    Write-Host "  [WAIT] $RlWindow s for the window to reset" -ForegroundColor DarkYellow
    Start-Sleep -Seconds $RlWindow
    $r = Send-Payment "alice@sbi" "bob@sbi" 100 "rl-recovery" -NoRetry
    Assert-That ($r.httpCode -eq 200 -and $r.status -eq "SUCCESS") "http=$($r.httpCode) status=$($r.status)"

    Start-Case "P5-04" "Second API key has an independent quota"
    if ($ApiKey2) {
        $k = "rl-key2-$RUN_ID"
        $r = Invoke-GW -Path "/api/v1/payments" -Method POST -Key $ApiKey2 -IdemKey $k -Body @{
            payer_vpa = "alice@sbi"; payee_vpa = "bob@sbi"; amount_paise = 100
            idempotency_key = $k; remarks = "smoke-$RUN_ID-second-key"
        }
        Assert-That ($r.httpCode -eq 200) "http=$($r.httpCode)"
    } else {
        Write-Host "    [SKIP] set IBTS_API_KEY_2 or pass -ApiKey2 to run this case" -ForegroundColor DarkYellow
    }
}

# ======================= RESULTS =======================
$total = $script:Pass + $script:Fail
$color = if ($script:Fail -eq 0) { "Green" } else { "Yellow" }
Write-Host ""
Write-Host "====================================================" -ForegroundColor White
Write-Host ("  TARGET : {0}" -f $BaseUrl) -ForegroundColor DarkGray
Write-Host ("  RUN ID : {0}" -f $RUN_ID)  -ForegroundColor DarkGray
Write-Host ("  PASSED : {0}/{1}" -f $script:Pass, $total) -ForegroundColor $color
if ($script:Fail -gt 0) {
    Write-Host ("  FAILED : {0}/{1} -- review [FAIL] lines above" -f $script:Fail, $total) -ForegroundColor Red
} else {
    Write-Host "  All executed tests passed" -ForegroundColor Green
}
Write-Host "====================================================" -ForegroundColor White

if ($ReportPath) {
    [pscustomobject]@{
        runId = $RUN_ID; target = $BaseUrl; passed = $script:Pass; failed = $script:Fail; results = $script:Results
    } | ConvertTo-Json -Depth 4 | Set-Content -Path $ReportPath -Encoding UTF8
    Write-Host "  Report written to $ReportPath" -ForegroundColor DarkGray
}

if ($script:Fail -gt 0) { exit 1 }
exit 0
